description:
With a pure `update(state, action)` function (lesson 6.05), undo is just keeping old states. Write a wrapper that adds history to any update function:

```javascript
function withHistory(update, limit = 50) { }
```

It returns a new update function that works on `{ past, present, future }`:

```javascript
const counter = (n, action) => (action.type === "add" ? n + action.by : n);
const update = withHistory(counter);
let h = { past: [], present: 0, future: [] };
h = update(h, { type: "add", by: 5 });   // { past: [0], present: 5, future: [] }
h = update(h, { type: "undo" });         // { past: [], present: 0, future: [5] }
h = update(h, { type: "redo" });         // { past: [0], present: 5, future: [] }
```

- Any action other than `undo` and `redo` goes to the inner `update`. If it returns the **same** present (`===`), nothing changes and the same history object is returned. Otherwise the old present joins `past`, and `future` is cleared.
- `undo` with nothing in `past`, and `redo` with nothing in `future`, return the same history object.
- `past` keeps at most `limit` states: the oldest are dropped.
- The function never changes the history object it is given.

starter.solution.js:
function withHistory(update, limit = 50) {
  return (history, action) => ({ ...history, present: update(history.present, action) });
}

solution.solution.js:
function withHistory(update, limit = 50) {
  return (history, action) => {
    const { past, present, future } = history;
    if (action.type === "undo") {
      if (past.length === 0) return history;
      return { past: past.slice(0, -1), present: past[past.length - 1], future: [present, ...future] };
    }
    if (action.type === "redo") {
      if (future.length === 0) return history;
      return { past: [...past, present], present: future[0], future: future.slice(1) };
    }
    const next = update(present, action);
    if (next === present) return history;
    return { past: [...past, present].slice(-limit), present: next, future: [] };
  };
}

unitTests:
const counter = (n, action) => (action.type === "add" ? n + action.by : n);
const start = () => ({ past: [], present: 0, future: [] });

test("the example", () => {
  const update = withHistory(counter);
  let h = update(start(), { type: "add", by: 5 });
  checkEq(h, { past: [0], present: 5, future: [] });
  h = update(h, { type: "undo" });
  checkEq(h, { past: [], present: 0, future: [5] });
  h = update(h, { type: "redo" });
  checkEq(h, { past: [0], present: 5, future: [] });
});

test("a new action clears the future", () => {
  const update = withHistory(counter);
  let h = start();
  for (const by of [1, 2, 3]) h = update(h, { type: "add", by });
  h = update(h, { type: "undo" });
  h = update(h, { type: "undo" });
  checkEq(h, { past: [0], present: 1, future: [3, 6] });
  h = update(h, { type: "add", by: 10 });
  checkEq(h, { past: [0, 1], present: 11, future: [] });
});

test("nothing to do returns the same object", () => {
  const update = withHistory(counter);
  const h = start();
  check(update(h, { type: "undo" }) === h, "undo with no past");
  check(update(h, { type: "redo" }) === h, "redo with no future");
  check(update(h, { type: "unknown" }) === h, "an action that changes nothing");
});

test("the limit and no mutation", () => {
  const update = withHistory(counter, 3);
  let h = start();
  for (let i = 0; i < 6; i++) h = update(h, { type: "add", by: 1 });
  checkEq(h.past, [3, 4, 5]);
  const frozen = JSON.stringify(h);
  update(h, { type: "undo" });
  update(h, { type: "add", by: 1 });
  checkEq(JSON.stringify(h), frozen);
});

